package com.manishrawat.realestate.dao; import com.manishrawat.realestate.model.Application; import com.manishrawat.realestate.util.DBConnection; import java.sql.*; import java.util.*;
public class ApplicationDAO { public boolean apply(int pid,int tid,String msg)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO rental_applications(property_id,tenant_id,message) VALUES(?,?,?)")){p.setInt(1,pid);p.setInt(2,tid);p.setString(3,msg);return p.executeUpdate()>0;}}
 public List<Application> forTenant(int tid)throws Exception{return list("SELECT a.*,p.title property_title,u.name tenant_name FROM rental_applications a JOIN properties p ON a.property_id=p.id JOIN users u ON a.tenant_id=u.id WHERE a.tenant_id="+tid);}
 public List<Application> all()throws Exception{return list("SELECT a.*,p.title property_title,u.name tenant_name FROM rental_applications a JOIN properties p ON a.property_id=p.id JOIN users u ON a.tenant_id=u.id ORDER BY a.id DESC");}
 public void status(int id,String s)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE rental_applications SET status=? WHERE id=?")){p.setString(1,s);p.setInt(2,id);p.executeUpdate();}}
 private List<Application> list(String q)throws Exception{List<Application> l=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next()){Application a=new Application();a.id=r.getInt("id");a.propertyId=r.getInt("property_id");a.tenantId=r.getInt("tenant_id");a.status=r.getString("status");a.message=r.getString("message");a.propertyTitle=r.getString("property_title");a.tenantName=r.getString("tenant_name");l.add(a);}}return l;}}
